deployment.program:
import credits.aleo;
import multi_dao_support_program.aleo;
import daom__approved_proposer_list.aleo;
import multi_token_support_programv1.aleo;

program treasury__dao_based.aleo;

struct Dao:
    dao_id as field;
    token_id as field;
    dao_manager as address;

struct Proposal:
    proposal_id as field;
    dao_id as field;
    content as field;
    voting_system as address;
    vs_params_hash as field;

struct ProposalKey:
    dao_id as field;
    proposal_id as field;

struct VotingSystemKey:
    dao_id as field;
    voting_system as address;
    vs_params_hash as field;

struct ProposerKey:
    dao_id as field;
    proposer as address;

struct TokenMetadata:
    token_id as field;
    name as u128;
    symbol as u128;
    decimals as u8;
    supply as u128;
    max_supply as u128;
    admin as address;
    external_authorization_required as boolean;
    external_authorization_party as address;

struct TokenOwner:
    account as address;
    token_id as field;

struct HookedTransfer:
    proposal_id as field;
    token_id as field;
    recipient as address;
    amount as u128;
    triggering_result as field;

mapping hooked_transfers:
    key as field.public;
    value as HookedTransfer.public;

function transfer_public:
    input r0 as HookedTransfer.public;
    cast 123field r0.proposal_id into r1 as ProposalKey;
    hash.bhp256 r1 into r2 as field;
    call multi_token_support_programv1.aleo/transfer_public r0.token_id r0.recipient r0.amount into r3;
    async transfer_public r0 r2 r3 into r4;
    output r4 as treasury__dao_based.aleo/transfer_public.future;

finalize transfer_public:
    input r0 as HookedTransfer.public;
    input r1 as field.public;
    input r2 as multi_token_support_programv1.aleo/transfer_public.future;
    await r2;
    get multi_dao_support_program.aleo/results[r1] into r3;
    assert.eq r3 r0.triggering_result;
    get hooked_transfers[r0.proposal_id] into r4;
    assert.eq r0 r4;

function hook_transfer_to_proposal:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as address.public;
    input r3 as u128.public;
    input r4 as field.public;
    cast 123field self.caller into r5 as ProposerKey;
    hash.bhp256 r5 into r6 as field;
    cast 123field r0 into r7 as ProposalKey;
    hash.bhp256 r7 into r8 as field;
    cast r0 r1 r2 r3 r4 into r9 as HookedTransfer;
    async hook_transfer_to_proposal r9 r8 r6 into r10;
    output r10 as treasury__dao_based.aleo/hook_transfer_to_proposal.future;

finalize hook_transfer_to_proposal:
    input r0 as HookedTransfer.public;
    input r1 as field.public;
    input r2 as field.public;
    get daom__approved_proposer_list.aleo/approved_proposers[r2] into r3;
    assert.eq r3 true;
    contains multi_dao_support_program.aleo/proposals[r1] into r4;
    not r4 into r5;
    assert.eq r5 true;
    set r0 into hooked_transfers[r0.proposal_id];
